Section LEAF.
Context {O : Type} (pans : O -> aptr -> Z -> Z -> Z) (pupd : O -> ev -> Z -> O).
Lemma alloc_slot_follow_mono lay f f' R st sc req (k : mstate -> Z -> M R) bail o ans r :
  (f <= f')%nat ->
  follow (prun pans pupd o (alloc_slot lay f st sc req k bail)) ans = Some r ->
